SELECT sku, gtin, name, pack, case_units, case_kg, flow, dc_slot, price_inr, cost_inr
FROM store.products
ORDER BY sku;

SELECT SUM(units_sold) AS units_sold, SUM(revenue_inr) AS revenue_inr, COUNT(*) AS days
FROM store.daily_sales
WHERE sku = 'ATTA-WW-5KG' AND date >= '2026-06-01' AND date < '2026-07-01';

SELECT SUM(qty) AS units_sold, COUNT(DISTINCT bill_id) AS bills, COUNT(*) AS lines
FROM store.pos_lines
WHERE sku_scanned = 'ATTA-WW-5KG' AND bill_ts >= '2026-06-01' AND bill_ts < '2026-07-01';

SELECT MIN(date), MAX(date) FROM store.daily_sales;
SELECT MIN(audit_ts), MAX(audit_ts), COUNT(*) FROM store.shelf_audits;
SELECT MIN(bill_ts), MAX(bill_ts) FROM store.pos_lines;

SELECT COUNT(DISTINCT bill_id) AS total_bills_june
FROM store.pos_lines
WHERE bill_ts >= '2026-06-01' AND bill_ts < '2026-07-01';
